func TestAssuranceRestoreMidbandReplay(t *testing.T) {
	cases := []struct {
		name        string
		secondBatch int
		event       string
	}{
		{name: "midband_replay", secondBatch: 3200, event: "mb_case_midband_replay"},
		{name: "capacity_replay", secondBatch: 8194, event: "mb_case_capacity_replay"},
		{name: "over_capacity_replay", secondBatch: 8195, event: "mb_case_over_capacity_replay"},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			mbRunCase(t, tc.name, tc.event, tc.secondBatch)
		})
	}
}

func mbRunCase(t *testing.T, name string, caseEvent string, secondBatch int) {
	t.Helper()
	const firstBatch = 200
	const window = 20 * time.Second

	store := NewInmemCommitTrackingStore()
	snaps := NewInmemSnapshotStore()
	conf := mbConfig("node1")
	_, trans := NewInmemTransport("node1")
	configuration := Configuration{Servers: []Server{{Suffrage: Voter, ID: "node1", Address: trans.LocalAddr()}}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &mbFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("producing raft: %v", err)
	}
	deadline := time.Now().Add(10 * time.Second)
	for r.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(2 * time.Millisecond)
	}
	if r.Leader() == "" {
		t.Fatalf("no leader")
	}
	apply := func(n int) {
		var last ApplyFuture
		for i := 0; i < n; i++ {
			last = r.Apply([]byte("x"), 5*time.Second)
		}
		if err := last.Error(); err != nil {
			t.Fatalf("apply: %v", err)
		}
	}
	apply(firstBatch)
	if err := r.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	apply(secondBatch)
	snapshotIndex := uint64(0)
	listed, err := snaps.List()
	if err != nil {
		t.Fatalf("list snapshots: %v", err)
	}
	if len(listed) > 0 {
		snapshotIndex = listed[0].Index
	}
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}
	staged, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("staged commit: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last log: %v", err)
	}
	replay := uint64(0)
	if staged > snapshotIndex {
		replay = staged - snapshotIndex
	}
	batches := (replay + 63) / 64

	mbEmit(t, map[string]interface{}{
		"event":                  caseEvent,
		"case":                   name,
		"mode":                   "real_cluster_restart_with_snapshot_bound_tail",
		"restore_committed_logs": true,
		"first_batch":            firstBatch,
		"second_batch":           secondBatch,
		"snapshot_index":         snapshotIndex,
		"staged_commit_index":    staged,
		"last_log_index":         lastLog,
		"replay_entries":         replay,
		"replay_batches":         batches,
		"max_append_entries":     64,
		"window_ms":              int(window / time.Millisecond),
	})

	base := mbBlocked()
	start := time.Now()
	done := make(chan error, 1)
	var restarted *Raft
	go func() {
		var rerr error
		restarted, rerr = NewRaft(mbConfig("node1"), &mbFSM{}, store, store, snaps, trans)
		done <- rerr
	}()
	returned := false
	errText := ""
	select {
	case err := <-done:
		returned = true
		if err != nil {
			errText = err.Error()
		} else {
			defer func() { _ = restarted.Shutdown().Error() }()
		}
	case <-time.After(window):
		errText = "no return within observation window"
	}
	mbEmit(t, map[string]interface{}{
		"event":               strings.Replace(caseEvent, "mb_case_", "mb_result_", 1),
		"case":                name,
		"returned":            returned,
		"elapsed_ms":          int(time.Since(start) / time.Millisecond),
		"error":               errText,
		"new_blocked_process": mbBlocked() - base,
	})
	t.Logf("case=%s replay=%d batches=%d returned=%v err=%q", name, replay, batches, returned, errText)
}

package raft

// Construction notes:
//   * One real four-member cluster is bootstrapped, one non-leader member is
//     demoted with DemoteVoter, and the harness waits until that member's own
//     configuration view reports the non-voter role.
//   * The control then calls LeadershipTransfer(), the automatic form that has no
//     target, and records whether a leader exists afterwards and whether it is a
//     voter.
//   * The trigger calls LeadershipTransferToServer for the demoted member and
//     records the future result, whether that member ever reports Leader, and the
//     sampled interval without a leader.
//   * The point of the pair is the asymmetry between the two entry points on the
//     same cluster state.

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"time"
)

func xgEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func xgRun(t *testing.T, name string, explicit bool) {
	t.Helper()
	const sampleEvery = 10 * time.Millisecond
	const watchWindow = 3 * time.Second

	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	defer c.Close()

	// Choose the member to demote at the moment of the demotion, so the target is
	// definitely a follower then: demoting the sitting leader starts a transfer of
	// its own and would contaminate the case.
	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var target *Raft
	for _, r := range c.rafts {
		if r.localID != leader.localID {
			target = r
			break
		}
	}
	if target == nil {
		t.Fatalf("no non-leader peer")
	}
	targetID := target.localID
	demotedWasLeader := leader.localID == targetID

	if err := leader.DemoteVoter(targetID, 0, 5*time.Second).Error(); err != nil {
		t.Fatalf("demote: %v", err)
	}
	roleOf := func() string {
		fut := target.GetConfiguration()
		if err := fut.Error(); err != nil {
			return "unknown"
		}
		for _, srv := range fut.Configuration().Servers {
			if srv.ID == targetID {
				if srv.Suffrage == Voter {
					return "voter"
				}
				return "nonvoter"
			}
		}
		return "absent"
	}
	convergeStart := time.Now()
	converged := false
	for time.Since(convergeStart) < 2*time.Second {
		if roleOf() == "nonvoter" {
			converged = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	convergeMS := int(time.Since(convergeStart) / time.Millisecond)

	mode := "automatic"
	if explicit {
		mode = "explicit_to_demoted_member"
	}
	xgEmit(t, map[string]interface{}{
		"event":              "xg_case_" + name,
		"case":               name,
		"mode":               mode,
		"members":            4,
		"voters":             3,
		"nonvoters":          1,
		"demoted_member":     string(targetID),
		"role_view":          roleOf(),
		"converged":          converged,
		"converge_ms":        convergeMS,
		"leader_before":      string(leader.localID),
		"demoted_was_leader": demotedWasLeader,
	})

	futureOK := false
	futureErr := ""
	futureDone := false
	attempts := 0
	start := time.Now()
	attemptErrors := []string{}
	firstAttemptOK := false
	firstAttemptErr := ""
	for attempts < 5 {
		transferLeader := c.Leader()
		if transferLeader == nil {
			futureErr = "no leader at transfer time"
			attemptErrors = append(attemptErrors, futureErr)
			break
		}
		fut := transferLeader.LeadershipTransfer()
		if explicit {
			fut = transferLeader.LeadershipTransferToServer(targetID, target.localAddr)
		}
		attempts++
		done := make(chan error, 1)
		go func() { done <- fut.Error() }()
		var err error
		select {
		case err = <-done:
			futureDone = true
		case <-time.After(5 * time.Second):
			err = fmt.Errorf("no completion within five seconds")
		}
		attemptErrText := ""
		if err != nil {
			attemptErrText = err.Error()
		}
		attemptErrors = append(attemptErrors, attemptErrText)
		if attempts == 1 {
			firstAttemptOK = err == nil
			firstAttemptErr = attemptErrText
		}
		if err == nil {
			futureOK = true
			futureErr = ""
			break
		}
		futureErr = err.Error()
		if !strings.Contains(futureErr, "in progress") {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}
	futureMS := int(time.Since(start) / time.Millisecond)

	samples := 0
	leaderless := 0
	targetEverLeader := false
	watchStart := time.Now()
	for time.Since(watchStart) < watchWindow {
		l := c.Leader()
		samples++
		if l == nil {
			leaderless++
		} else if l.localID == targetID {
			targetEverLeader = true
		}
		time.Sleep(sampleEvery)
	}
	finalLeader := ""
	finalIsTarget := false
	if l := c.Leader(); l != nil {
		finalLeader = string(l.localID)
		finalIsTarget = l.localID == targetID
	}

	// Whatever the transfer did to the leader's transfer state, a client write
	// submitted afterwards shows whether the leader still serves requests.
	applyErr := ""
	applyMs := 0
	configErr := ""
	if l := c.Leader(); l == nil {
		applyErr = "no leader"
		configErr = "no leader"
	} else {
		applyStart := time.Now()
		if err := l.Apply([]byte("post-transfer"), 2*time.Second).Error(); err != nil {
			applyErr = err.Error()
		}
		applyMs = int(time.Since(applyStart) / time.Millisecond)
		if err := l.GetConfiguration().Error(); err != nil {
			configErr = err.Error()
		}
	}

	xgEmit(t, map[string]interface{}{
		"event":                  "xg_result_" + name,
		"case":                   name,
		"mode":                   mode,
		"future_done":            futureDone,
		"future_ok":              futureOK,
		"future_error":           futureErr,
		"future_ms":              futureMS,
		"attempts":               attempts,
		"attempt_errors":         attemptErrors,
		"first_attempt_ok":       firstAttemptOK,
		"first_attempt_error":    firstAttemptErr,
		"target_became_leader":   targetEverLeader,
		"samples":                samples,
		"leaderless_samples":     leaderless,
		"leaderless_ms_at_least": leaderless * int(sampleEvery/time.Millisecond),
		"final_leader":           finalLeader,
		"final_leader_is_target": finalIsTarget,
		"final_leader_is_voter":  finalLeader != "" && !finalIsTarget,
		"post_apply_error":       applyErr,
		"post_apply_ms":          applyMs,
		"post_config_error":      configErr,
	})
	t.Logf("case=%s mode=%s futureOK=%v err=%q targetLeader=%v leaderless=%d final=%q",
		name, mode, futureOK, futureErr, targetEverLeader, leaderless, finalLeader)
}

func TestAssuranceTransferAutomaticVsExplicit(t *testing.T) {
	t.Run("control_automatic_transfer", func(t *testing.T) {
		xgRun(t, "control_automatic_transfer", false)
	})
	t.Run("trigger_explicit_to_demoted", func(t *testing.T) {
		xgRun(t, "trigger_explicit_to_demoted", true)
	})
}

package raft

// Construction notes:
//   * Each case bootstraps its own four-member cluster, demotes one follower and
//     waits until that member's own configuration view reports the non-voter
//     role, so the target is known to be ineligible before the transfer starts.
//   * The single case issues exactly one explicit transfer, sampling the
//     leader's transfer flag before the call, immediately after the call returns
//     its future, after the future completes and after a short settle.
//   * The retry case reproduces the five-attempt sequence and samples the flag
//     before every attempt, so an in-progress error can be attributed either to
//     a prior request still running or to the request that produced it.

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"time"
)

func fwEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type fwSetup struct {
	cluster []*Raft
	leader  *Raft
	target  *Raft
}

func fwPrepare(t *testing.T, name string) (fwSetup, bool) {
	t.Helper()
	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	leader := c.Leader()
	if leader == nil {
		c.Close()
		t.Fatalf("no leader")
	}
	var target *Raft
	for _, r := range c.rafts {
		if r.localID != leader.localID {
			target = r
			break
		}
	}
	if target == nil {
		c.Close()
		t.Fatalf("no non-leader peer")
	}
	targetID := target.localID
	if err := leader.DemoteVoter(targetID, 0, 5*time.Second).Error(); err != nil {
		c.Close()
		t.Fatalf("demote: %v", err)
	}
	role := func() string {
		fut := target.GetConfiguration()
		if err := fut.Error(); err != nil {
			return "unknown"
		}
		for _, srv := range fut.Configuration().Servers {
			if srv.ID == targetID {
				if srv.Suffrage == Voter {
					return "voter"
				}
				return "nonvoter"
			}
		}
		return "absent"
	}
	convergeStart := time.Now()
	converged := false
	for time.Since(convergeStart) < 2*time.Second {
		if role() == "nonvoter" {
			converged = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	x := fwSetup{cluster: c.rafts, leader: leader, target: target}
	fwEmit(t, map[string]interface{}{
		"event":         "fw_case_" + name,
		"case":          name,
		"members":       4,
		"demoted":       string(targetID),
		"role_view":     role(),
		"converged":     converged,
		"converge_ms":   int(time.Since(convergeStart) / time.Millisecond),
		"leader_before": string(leader.localID),
	})
	return x, converged
}

func fwWatchLeader(target *Raft, members []*Raft, window time.Duration) (bool, int, int, string) {
	targetEverLeader := false
	leaderless := 0
	samples := 0
	deadline := time.Now().Add(window)
	for time.Now().Before(deadline) {
		samples++
		found := ""
		for _, r := range members {
			if r.State() == Leader {
				found = string(r.localID)
				if r.localID == target.localID {
					targetEverLeader = true
				}
				break
			}
		}
		if found == "" {
			leaderless++
		}
		time.Sleep(10 * time.Millisecond)
	}
	final := ""
	for _, r := range members {
		if r.State() == Leader {
			final = string(r.localID)
			break
		}
	}
	return targetEverLeader, leaderless, samples, final
}

func TestAssuranceTransferFlagWindow(t *testing.T) {
	t.Run("single_explicit_attempt", func(t *testing.T) {
		x, converged := fwPrepare(t, "single_explicit_attempt")
		if !converged {
			t.Fatalf("demotion did not converge on the target")
		}
		before := x.leader.getLeadershipTransferInProgress()
		fut := x.leader.LeadershipTransferToServer(x.target.localID, x.target.localAddr)
		afterCall := x.leader.getLeadershipTransferInProgress()
		start := time.Now()
		done := make(chan error, 1)
		go func() { done <- fut.Error() }()
		var err error
		completed := false
		select {
		case err = <-done:
			completed = true
		case <-time.After(5 * time.Second):
		}
		elapsed := int(time.Since(start) / time.Millisecond)
		afterFuture := x.leader.getLeadershipTransferInProgress()
		time.Sleep(300 * time.Millisecond)
		settled := x.leader.getLeadershipTransferInProgress()
		errText := ""
		if err != nil {
			errText = err.Error()
		}
		targetLed, leaderless, samples, final := fwWatchLeader(x.target, x.cluster, 3*time.Second)
		fwEmit(t, map[string]interface{}{
			"event":                "fw_result_single_explicit_attempt",
			"case":                 "single_explicit_attempt",
			"flag_before":          before,
			"flag_after_call":      afterCall,
			"flag_after_future":    afterFuture,
			"flag_after_300ms":     settled,
			"future_completed":     completed,
			"future_error":         errText,
			"future_ms":            elapsed,
			"attempts":             1,
			"target_became_leader": targetLed,
			"leaderless_samples":   leaderless,
			"samples":              samples,
			"final_leader":         final,
			"final_is_target":      final != "" && final == string(x.target.localID),
		})
	})

	t.Run("retry_sequence_explicit", func(t *testing.T) {
		x, converged := fwPrepare(t, "retry_sequence_explicit")
		if !converged {
			t.Fatalf("demotion did not converge on the target")
		}
		flagBeforeFirst := x.leader.getLeadershipTransferInProgress()
		attemptErrors := []string{}
		flagsBefore := []bool{}
		attempts := 0
		for attempts < 5 {
			current := x.leader
			for _, r := range x.cluster {
				if r.State() == Leader {
					current = r
					break
				}
			}
			flagsBefore = append(flagsBefore, current.getLeadershipTransferInProgress())
			fut := current.LeadershipTransferToServer(x.target.localID, x.target.localAddr)
			attempts++
			done := make(chan error, 1)
			go func() { done <- fut.Error() }()
			var err error
			select {
			case err = <-done:
			case <-time.After(5 * time.Second):
				err = fmt.Errorf("no completion within five seconds")
			}
			text := ""
			if err != nil {
				text = err.Error()
			}
			attemptErrors = append(attemptErrors, text)
			if err == nil || !strings.Contains(text, "in progress") {
				break
			}
			time.Sleep(100 * time.Millisecond)
		}
		targetLed, leaderless, samples, final := fwWatchLeader(x.target, x.cluster, 3*time.Second)
		fwEmit(t, map[string]interface{}{
			"event":                "fw_result_retry_sequence_explicit",
			"case":                 "retry_sequence_explicit",
			"flag_before_first":    flagBeforeFirst,
			"flags_before_attempt": flagsBefore,
			"attempt_errors":       attemptErrors,
			"attempts":             attempts,
			"target_became_leader": targetLed,
			"leaderless_samples":   leaderless,
			"samples":              samples,
			"final_leader":         final,
			"final_is_target":      final != "" && final == string(x.target.localID),
		})
	})
}

package raft

// Construction notes:
//   * Three real nodes over in-memory transports. A and B are bootstrapped as the
//     committed voter set; C runs with no configuration and is reachable.
//   * The leader's log store fails exactly the write that would carry AddVoter(C),
//     so the in-memory latest configuration grows to include C while the stored
//     log never receives that entry.
//   * The leader is cut from the other committed voter but stays reachable to C,
//     applies a command with the phantom quorum, and is then shut down.
//   * A fresh Raft is started over the same stores and transport, and the probe
//     records the configuration it loads and whether the stored log contains the
//     entry that was committed under the phantom configuration.

import (
	"encoding/json"
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

func prEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type prFailStore struct {
	*InmemStore
	mu       sync.Mutex
	failNext bool
}

func newPrFailStore() *prFailStore { return &prFailStore{InmemStore: NewInmemStore()} }

func (f *prFailStore) StoreLogs(logs []*Log) error {
	f.mu.Lock()
	fail := f.failNext
	f.failNext = false
	f.mu.Unlock()
	if fail {
		return fmt.Errorf("injected store failure")
	}
	return f.InmemStore.StoreLogs(logs)
}

type prFSM struct{ applied int }

func (f *prFSM) Apply(*Log) interface{}         { f.applied++; return nil }
func (f *prFSM) Snapshot() (FSMSnapshot, error) { return &prSnap{}, nil }
func (f *prFSM) Restore(io.ReadCloser) error    { f.applied = 0; return nil }

type prSnap struct{}

func (s *prSnap) Persist(SnapshotSink) error { return nil }
func (s *prSnap) Release()                   {}

func TestAssurancePhantomConfigRestart(t *testing.T) {
	base := inmemConfig(t)
	base.HeartbeatTimeout = 300 * time.Millisecond
	base.ElectionTimeout = 300 * time.Millisecond
	base.LeaderLeaseTimeout = 300 * time.Millisecond

	addrA, transA := NewInmemTransport("A")
	addrB, transB := NewInmemTransport("B")
	addrC, transC := NewInmemTransport("C")
	transA.Connect(addrB, transB)
	transA.Connect(addrC, transC)
	transB.Connect(addrA, transA)
	transB.Connect(addrC, transC)
	transC.Connect(addrA, transA)
	transC.Connect(addrB, transB)

	storeA, storeB := newPrFailStore(), newPrFailStore()
	storeC := NewInmemStore()
	snapsA, snapsB, snapsC := NewInmemSnapshotStore(), NewInmemSnapshotStore(), NewInmemSnapshotStore()
	committed := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "A", Address: addrA},
		{Suffrage: Voter, ID: "B", Address: addrB},
	}}

	confA := *base
	confA.LocalID = "A"
	confB := *base
	confB.LocalID = "B"
	confC := *base
	confC.LocalID = "C"
	if err := BootstrapCluster(&confA, storeA, storeA, snapsA, transA, committed); err != nil {
		t.Fatalf("bootstrap A: %v", err)
	}
	if err := BootstrapCluster(&confB, storeB, storeB, snapsB, transB, committed); err != nil {
		t.Fatalf("bootstrap B: %v", err)
	}

	rA, err := NewRaft(&confA, &prFSM{}, storeA, storeA, snapsA, transA)
	if err != nil {
		t.Fatalf("raft A: %v", err)
	}
	rB, err := NewRaft(&confB, &prFSM{}, storeB, storeB, snapsB, transB)
	if err != nil {
		_ = rA.Shutdown().Error()
		t.Fatalf("raft B: %v", err)
	}
	defer func() { _ = rB.Shutdown().Error() }()
	rC, err := NewRaft(&confC, &prFSM{}, storeC, storeC, snapsC, transC)
	if err != nil {
		_ = rA.Shutdown().Error()
		t.Fatalf("raft C: %v", err)
	}
	defer func() { _ = rC.Shutdown().Error() }()

	deadline := time.Now().Add(10 * time.Second)
	for rA.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	if rA.Leader() == "" {
		t.Fatalf("no leader formed in the two-voter committed configuration")
	}

	rL, rP := rA, rB
	stL := storeA
	confL := &confA
	snapsL := snapsA
	transL, transP := transA, transB
	addrL, addrP := addrA, addrB
	if rA.Leader() == "B" {
		rL, rP = rB, rA
		stL = storeB
		confL = &confB
		snapsL = snapsB
		transL, transP = transB, transA
		addrL, addrP = addrB, addrA
	}
	_ = rP

	stL.mu.Lock()
	stL.failNext = true
	stL.mu.Unlock()
	errAdd := rL.AddVoter("C", addrC, 0, 5*time.Second).Error()
	lastLogL, _ := stL.LastIndex()
	latestIndex := rL.configurations.latestIndex
	latestServers := rL.getLatestConfiguration().Servers

	transL.Disconnect(addrP)
	transP.Disconnect(addrL)
	deadline = time.Now().Add(10 * time.Second)
	for rL.State() != Leader && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	applyErr := rL.Apply([]byte("phantom-restart"), 3*time.Second).Error()
	commitL := rL.CommitIndex()
	lastL, _ := stL.LastIndex()
	lastP, _ := storeB.LastIndex()
	if rL.localID == "B" {
		lastP, _ = storeA.LastIndex()
	}
	prEmit(t, map[string]interface{}{
		"event":                     "pr_case_phantom_commit",
		"case":                      "phantom_commit",
		"add_failed":                errAdd != nil,
		"latest_index_after_fail":   latestIndex,
		"last_log_index_after_fail": lastLogL,
		"phantom_voters":            len(latestServers),
		"apply_ok":                  applyErr == nil,
		"commit_index":              commitL,
		"leader_last_index":         lastL,
		"committed_peer_last_index": lastP,
		"committed_peer_has_entry":  lastP >= commitL,
	})

	if err := rL.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown leader: %v", err)
	}

	restarted, err := NewRaft(confL, &prFSM{}, stL, stL, snapsL, transL)
	if err != nil {
		t.Fatalf("restart leader raft: %v", err)
	}
	defer func() { _ = restarted.Shutdown().Error() }()
	var loaded Configuration
	cfgErr := restarted.GetConfiguration().Error()
	if cfgErr == nil {
		loaded = restarted.GetConfiguration().Configuration()
	}
	loadedIDs := []string{}
	loadedHasC := false
	loadedVoters := 0
	for _, srv := range loaded.Servers {
		loadedIDs = append(loadedIDs, string(srv.ID))
		if srv.ID == "C" {
			loadedHasC = true
		}
		if srv.Suffrage == Voter {
			loadedVoters++
		}
	}
	restartLast, _ := stL.LastIndex()
	restartCommit := uint64(0)
	prEmit(t, map[string]interface{}{
		"event":                          "pr_result_phantom_restart",
		"case":                           "phantom_restart",
		"config_error":                   fmt.Sprintf("%v", cfgErr),
		"restarted_servers":              fmt.Sprintf("%v", loadedIDs),
		"restarted_has_new_server":       loadedHasC,
		"restarted_voters":               loadedVoters,
		"restart_last_log_index":         restartLast,
		"restart_commit_index":           restartCommit,
		"phantom_commit_index":           commitL,
		"stored_log_has_committed_entry": restartLast >= commitL,
		"phantom_survived_restart":       loadedHasC,
	})
	t.Logf("add_failed=%v applyErr=%v commit=%d lastL=%d lastP=%d restartLast=%d hasC=%v servers=%v",
		errAdd != nil, applyErr, commitL, lastL, lastP, restartLast, loadedHasC, loadedIDs)
}

package raft

// Construction notes:
//   * Three real nodes over in-memory transports. A and B are bootstrapped as the
//     committed voter set; C runs with no configuration and is reachable.
//   * The leader's log store fails exactly the write that would carry AddVoter(C),
//     so the in-memory latest configuration grows to include C while the stored
//     log never receives that entry.
//   * The leader is cut from the other committed voter but stays reachable to C,
//     applies a command with the phantom quorum, and is then shut down.
//   * A fresh Raft is started over the same stores and transport, and the probe
//     records the configuration it loads and whether the stored log contains the
//     entry that was committed under the phantom configuration.

import (
	"encoding/json"
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

func prEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type prFailStore struct {
	*InmemStore
	mu       sync.Mutex
	failNext bool
}

func newPrFailStore() *prFailStore { return &prFailStore{InmemStore: NewInmemStore()} }

func (f *prFailStore) StoreLogs(logs []*Log) error {
	f.mu.Lock()
	fail := f.failNext
	f.failNext = false
	f.mu.Unlock()
	if fail {
		return fmt.Errorf("injected store failure")
	}
	return f.InmemStore.StoreLogs(logs)
}

type prFSM struct{ applied int }

func (f *prFSM) Apply(*Log) interface{}         { f.applied++; return nil }
func (f *prFSM) Snapshot() (FSMSnapshot, error) { return &prSnap{}, nil }
func (f *prFSM) Restore(io.ReadCloser) error    { f.applied = 0; return nil }

type prSnap struct{}

func (s *prSnap) Persist(SnapshotSink) error { return nil }
func (s *prSnap) Release()                   {}

func TestAssurancePhantomConfigRestart(t *testing.T) {
	base := inmemConfig(t)
	base.HeartbeatTimeout = 300 * time.Millisecond
	base.ElectionTimeout = 300 * time.Millisecond
	base.LeaderLeaseTimeout = 300 * time.Millisecond

	addrA, transA := NewInmemTransport("A")
	addrB, transB := NewInmemTransport("B")
	addrC, transC := NewInmemTransport("C")
	transA.Connect(addrB, transB)
	transA.Connect(addrC, transC)
	transB.Connect(addrA, transA)
	transB.Connect(addrC, transC)
	transC.Connect(addrA, transA)
	transC.Connect(addrB, transB)

	storeA, storeB := newPrFailStore(), newPrFailStore()
	storeC := NewInmemStore()
	snapsA, snapsB, snapsC := NewInmemSnapshotStore(), NewInmemSnapshotStore(), NewInmemSnapshotStore()
	committed := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "A", Address: addrA},
		{Suffrage: Voter, ID: "B", Address: addrB},
	}}

	confA := *base
	confA.LocalID = "A"
	confB := *base
	confB.LocalID = "B"
	confC := *base
	confC.LocalID = "C"
	if err := BootstrapCluster(&confA, storeA, storeA, snapsA, transA, committed); err != nil {
		t.Fatalf("bootstrap A: %v", err)
	}
	if err := BootstrapCluster(&confB, storeB, storeB, snapsB, transB, committed); err != nil {
		t.Fatalf("bootstrap B: %v", err)
	}

	rA, err := NewRaft(&confA, &prFSM{}, storeA, storeA, snapsA, transA)
	if err != nil {
		t.Fatalf("raft A: %v", err)
	}
	rB, err := NewRaft(&confB, &prFSM{}, storeB, storeB, snapsB, transB)
	if err != nil {
		_ = rA.Shutdown().Error()
		t.Fatalf("raft B: %v", err)
	}
	defer func() { _ = rB.Shutdown().Error() }()
	rC, err := NewRaft(&confC, &prFSM{}, storeC, storeC, snapsC, transC)
	if err != nil {
		_ = rA.Shutdown().Error()
		t.Fatalf("raft C: %v", err)
	}
	defer func() { _ = rC.Shutdown().Error() }()

	deadline := time.Now().Add(10 * time.Second)
	for rA.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	if rA.Leader() == "" {
		t.Fatalf("no leader formed in the two-voter committed configuration")
	}

	rL, rP := rA, rB
	stL := storeA
	confL := &confA
	snapsL := snapsA
	transL, transP := transA, transB
	addrL, addrP := addrA, addrB
	if rA.Leader() == "B" {
		rL, rP = rB, rA
		stL = storeB
		confL = &confB
		snapsL = snapsB
		transL, transP = transB, transA
		addrL, addrP = addrB, addrA
	}
	_ = rP

	stL.mu.Lock()
	stL.failNext = true
	stL.mu.Unlock()
	errAdd := rL.AddVoter("C", addrC, 0, 5*time.Second).Error()
	lastLogL, _ := stL.LastIndex()
	latestIndex := rL.configurations.latestIndex
	latestServers := rL.getLatestConfiguration().Servers

	transL.Disconnect(addrP)
	transP.Disconnect(addrL)
	deadline = time.Now().Add(10 * time.Second)
	for rL.State() != Leader && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	applyErr := rL.Apply([]byte("phantom-restart"), 3*time.Second).Error()
	commitL := rL.CommitIndex()
	lastL, _ := stL.LastIndex()
	lastP, _ := storeB.LastIndex()
	if rL.localID == "B" {
		lastP, _ = storeA.LastIndex()
	}
	prEmit(t, map[string]interface{}{
		"event":                     "pr_case_phantom_commit",
		"case":                      "phantom_restart",
		"phase":                     "commit",
		"add_failed":                errAdd != nil,
		"latest_index_after_fail":   latestIndex,
		"last_log_index_after_fail": lastLogL,
		"phantom_voters":            len(latestServers),
		"apply_ok":                  applyErr == nil,
		"commit_index":              commitL,
		"leader_last_index":         lastL,
		"committed_peer_last_index": lastP,
		"committed_peer_has_entry":  lastP >= commitL,
	})

	if err := rL.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown leader: %v", err)
	}

	restarted, err := NewRaft(confL, &prFSM{}, stL, stL, snapsL, transL)
	if err != nil {
		t.Fatalf("restart leader raft: %v", err)
	}
	defer func() { _ = restarted.Shutdown().Error() }()
	var loaded Configuration
	cfgErr := restarted.GetConfiguration().Error()
	if cfgErr == nil {
		loaded = restarted.GetConfiguration().Configuration()
	}
	loadedIDs := []string{}
	loadedHasC := false
	loadedVoters := 0
	for _, srv := range loaded.Servers {
		loadedIDs = append(loadedIDs, string(srv.ID))
		if srv.ID == "C" {
			loadedHasC = true
		}
		if srv.Suffrage == Voter {
			loadedVoters++
		}
	}
	restartLast, _ := stL.LastIndex()
	restartCommit := uint64(0)
	prEmit(t, map[string]interface{}{
		"event":                          "pr_result_phantom_restart",
		"case":                           "phantom_restart",
		"config_error":                   fmt.Sprintf("%v", cfgErr),
		"restarted_servers":              fmt.Sprintf("%v", loadedIDs),
		"restarted_has_new_server":       loadedHasC,
		"restarted_voters":               loadedVoters,
		"restart_last_log_index":         restartLast,
		"restart_commit_index":           restartCommit,
		"phantom_commit_index":           commitL,
		"stored_log_has_committed_entry": restartLast >= commitL,
		"phantom_survived_restart":       loadedHasC,
	})
	t.Logf("add_failed=%v applyErr=%v commit=%d lastL=%d lastP=%d restartLast=%d hasC=%v servers=%v",
		errAdd != nil, applyErr, commitL, lastL, lastP, restartLast, loadedHasC, loadedIDs)
}

package raft

// Construction notes:
//   * Each case bootstraps five members, demotes two to non-voters, and cuts the
//     leader from the two remaining voters while leaving the non-voters
//     reachable, so the leader can reach only itself among voters.
//   * The case then repeats VerifyLeader every 50 ms and records how many
//     consecutive verifications succeeded and how long the first failure took.
//   * The two cases differ only in the configured lease and the timeouts above
//     it, so the measured window can be compared across settings.

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func vlEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func vlRun(t *testing.T, name string, lease, heartbeat, election, window time.Duration) {
	t.Helper()
	conf := inmemConfig(t)
	conf.LeaderLeaseTimeout = lease
	conf.HeartbeatTimeout = heartbeat
	conf.ElectionTimeout = election
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 5, Bootstrap: true, Conf: conf})
	defer c.Close()

	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var others []*Raft
	for _, r := range c.rafts {
		if r != leader {
			others = append(others, r)
		}
	}
	for _, r := range others[:2] {
		if err := leader.DemoteVoter(r.localID, 0, 5*time.Second).Error(); err != nil {
			t.Fatalf("demote: %v", err)
		}
	}
	time.Sleep(heartbeat / 2)

	leaderTrans := leader.trans.(*InmemTransport)
	for _, r := range others[2:] {
		leaderTrans.Disconnect(r.localAddr)
		r.trans.(*InmemTransport).Disconnect(leader.localAddr)
	}
	vlEmit(t, map[string]interface{}{
		"event":               "vl_case_" + name,
		"case":                name,
		"lease_ms":            int(lease / time.Millisecond),
		"heartbeat_ms":        int(heartbeat / time.Millisecond),
		"election_ms":         int(election / time.Millisecond),
		"members":             5,
		"nonvoters":           2,
		"voters":              3,
		"nonvoters_reachable": 2,
		"voters_reachable":    1,
	})

	firstStart := time.Now()
	firstErr := leader.VerifyLeader().Error()
	firstOK := firstErr == nil
	firstMS := int(time.Since(firstStart) / time.Millisecond)

	successes := 0
	msUntilFailure := -1
	loopStart := time.Now()
	for time.Since(loopStart) < window {
		f := leader.VerifyLeader()
		done := make(chan error, 1)
		go func() { done <- f.Error() }()
		var err error
		select {
		case err = <-done:
		case <-time.After(lease):
			err = fmt.Errorf("no completion")
		}
		if err == nil {
			successes++
			time.Sleep(50 * time.Millisecond)
			continue
		}
		msUntilFailure = int(time.Since(loopStart) / time.Millisecond)
		break
	}
	vlEmit(t, map[string]interface{}{
		"event":            "vl_result_" + name,
		"case":             name,
		"lease_ms":         int(lease / time.Millisecond),
		"heartbeat_ms":     int(heartbeat / time.Millisecond),
		"election_ms":      int(election / time.Millisecond),
		"members":          5,
		"nonvoters":        2,
		"first_verify_ok":  firstOK,
		"first_verify_ms":  firstMS,
		"loop_successes":   successes,
		"ms_until_failure": msUntilFailure,
		"window_ms":        int(window / time.Millisecond),
		"state_after":      leader.State().String(),
	})
	t.Logf("case=%s lease=%v firstOK=%v successes=%d msUntilFailure=%d",
		name, lease, firstOK, successes, msUntilFailure)
}

func TestAssuranceVerifyLeaseWindow(t *testing.T) {
	t.Run("lease_500ms", func(t *testing.T) {
		vlRun(t, "lease_500ms", 500*time.Millisecond, 500*time.Millisecond, 600*time.Millisecond, 2*time.Second)
	})
	t.Run("lease_1s", func(t *testing.T) {
		vlRun(t, "lease_1s", time.Second, time.Second, time.Second, 2500*time.Millisecond)
	})
}

package raft

// Construction notes:
//   * Each case bootstraps its own four-member in-memory cluster and demotes one
//     non-leader member only in the trigger case, waiting until that member's own
//     configuration view reports the non-voter role.
//   * Exactly one leader transfer request is issued per case, and the automatic
//     LeadershipTransfer() form is never called, so any leader change or term
//     advance observed afterwards belongs to the explicitly named target alone.
//   * Leader state and every member's current term are sampled every 10 ms for
//     five seconds, before and after the request.

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func etEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func etRole(r *Raft, id ServerID) string {
	fut := r.GetConfiguration()
	if err := fut.Error(); err != nil {
		return "unknown"
	}
	for _, srv := range fut.Configuration().Servers {
		if srv.ID == id {
			if srv.Suffrage == Voter {
				return "voter"
			}
			return "nonvoter"
		}
	}
	return "absent"
}

func etTermMax(rafts []*Raft) uint64 {
	var max uint64
	for _, r := range rafts {
		if term := r.CurrentTerm(); term > max {
			max = term
		}
	}
	return max
}

func etRun(t *testing.T, name string, demoteTarget bool) {
	t.Helper()
	const sampleEvery = 10 * time.Millisecond
	const watchWindow = 5 * time.Second

	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	defer c.Close()

	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var target *Raft
	for _, r := range c.rafts {
		if r.localID != leader.localID {
			target = r
			break
		}
	}
	if target == nil {
		t.Fatalf("no non-leader peer")
	}
	targetID := target.localID

	converged := true
	if demoteTarget {
		if err := leader.DemoteVoter(targetID, 0, 5*time.Second).Error(); err != nil {
			t.Fatalf("demote: %v", err)
		}
		converged = false
		deadline := time.Now().Add(2 * time.Second)
		for time.Now().Before(deadline) {
			if etRole(target, targetID) == "nonvoter" {
				converged = true
				break
			}
			time.Sleep(5 * time.Millisecond)
		}
	}

	termMaxBefore := etTermMax(c.rafts)
	etEmit(t, map[string]interface{}{
		"event":              "et_case_" + name,
		"case":               name,
		"members":            4,
		"target_demoted":     demoteTarget,
		"role_view":          etRole(target, targetID),
		"converged":          converged,
		"leader_before":      string(leader.localID),
		"target_term_before": target.CurrentTerm(),
		"term_max_before":    termMaxBefore,
		"watch_window_ms":    int(watchWindow / time.Millisecond),
		"sample_interval_ms": int(sampleEvery / time.Millisecond),
	})

	start := time.Now()
	fut := leader.LeadershipTransferToServer(targetID, target.localAddr)
	err := fut.Error()
	futureMillis := int(time.Since(start) / time.Millisecond)
	futureErr := ""
	if err != nil {
		futureErr = err.Error()
	}

	samples := 0
	leaderless := 0
	targetEverLeader := false
	termMaxAfter := termMaxBefore
	deadline := time.Now().Add(watchWindow)
	for time.Now().Before(deadline) {
		samples++
		if target.State() == Leader {
			targetEverLeader = true
		}
		sawLeader := false
		for _, r := range c.rafts {
			if r.State() == Leader {
				sawLeader = true
				break
			}
		}
		if !sawLeader {
			leaderless++
		}
		for _, r := range c.rafts {
			if term := r.CurrentTerm(); term > termMaxAfter {
				termMaxAfter = term
			}
		}
		time.Sleep(sampleEvery)
	}

	finalLeader := c.Leader()
	finalLeaderID := ""
	finalIsTarget := false
	if finalLeader != nil {
		finalLeaderID = string(finalLeader.localID)
		finalIsTarget = finalLeader.localID == targetID
	}

	etEmit(t, map[string]interface{}{
		"event":                    "et_result_" + name,
		"case":                     name,
		"future_error":             futureErr,
		"future_ms":                futureMillis,
		"target_became_leader":     targetEverLeader,
		"final_leader":             finalLeaderID,
		"final_is_target":          finalIsTarget,
		"leaderless_samples":       leaderless,
		"samples":                  samples,
		"term_max_before":          termMaxBefore,
		"term_max_after":           termMaxAfter,
		"terms_advanced":           termMaxAfter > termMaxBefore,
		"target_term_after":        target.CurrentTerm(),
		"target_role_after":        etRole(target, targetID),
	})
}

func TestAssuranceExplicitTransferCost(t *testing.T) {
	t.Run("demoted_target_only_request", func(t *testing.T) {
		etRun(t, "demoted_target_only_request", true)
	})
	t.Run("voter_target_control", func(t *testing.T) {
		etRun(t, "voter_target_control", false)
	})
}

